                if ((int) records[mid] < target) left = mid + 1;
                else right = mid;
            }
            return left;
        }

        private int countLessThan(int left, int right, int bound) {
            if (bound <= 0) return 0;
            if (bound >= valueCount) return right - left;

            int result = 0;
            for (int level = 0; level < levels; level++) {
                int bit = levels - 1 - level;
                int[] prefix = prefixZeros[level];
                int zeroLeft = prefix[left];
                int zeroRight = prefix[right];

                if (((bound >>> bit) & 1) != 0) {
                    result += zeroRight - zeroLeft;
                    left = zeroCounts[level] + (left - zeroLeft);
                    right = zeroCounts[level] + (right - zeroRight);
                } else {
                    left = zeroLeft;
                    right = zeroRight;
                }
            }
            return result;
        }

        // Returns (number of matching indices << 32) | count with rank < bound.
        long query(int key, int indexLeft, int indexRight, int bound) {
            int group = findGroup(key);
            if (group < 0) return 0;

            int start = groupStarts[group];
            int end = groupEnds[group];

            if (end - start <= 8) {
                int total = 0;
                int below = 0;
                for (int i = start; i < end; i++) {
                    int index = (int) records[i];
                    if (index >= indexLeft && index < indexRight) {
                        total++;
                        if (bound > 0 && ranksOfRecord(i) < bound) below++;
                    }
                }
                return ((long) total << 32) | (below & 0xffffffffL);
            }

            int left = lowerBoundIndex(start, end, indexLeft);
            int right = lowerBoundIndex(left, end, indexRight);
            int total = right - left;
            int below = countLessThan(left, right, bound);
            return ((long) total << 32) | (below & 0xffffffffL);
        }

        private int ranksOfRecord(int recordPosition) {
            return currentRanks[recordPosition];
        }

        private int[] currentRanks;

        void setCurrentRanks(int[] ranks) {
            currentRanks = new int[records.length];
            for (int i = 0; i < records.length; i++) {
                currentRanks[i] = ranks[(int) records[i]];
            }
        }
    }

    static int n;
    static int[] heights;
    static int[] heightRanks;
    static StaticIndex sumIndex;
    static StaticIndex diffIndex;
    static int[] parent, componentLeft, componentRight, componentSize;
    static boolean[] active;
    static int targetEnergy;
    static long currentPairs;

    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != x) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    static long getTotal(long packed) {
        return packed >>> 32;
    }

    static long getBelow(long packed) {
        return packed & 0xffffffffL;
    }

    static void merge(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) return;

        int leftRoot = componentLeft[rootA] < componentLeft[rootB] ? rootA : rootB;
        int rightRoot = leftRoot == rootA ? rootB : rootA;

        int leftSize = componentSize[leftRoot];
        int rightSize = componentSize[rightRoot];

        int smallRoot, largeRoot;
        boolean smallIsLeft;
        if (leftSize <= rightSize) {
            smallRoot = leftRoot;
            largeRoot = rightRoot;
            smallIsLeft = true;
        } else {
            smallRoot = rightRoot;
            largeRoot = leftRoot;
            smallIsLeft = false;
        }

        int smallL = componentLeft[smallRoot];
        int smallR = componentRight[smallRoot];
        int largeL = componentLeft[largeRoot];
        int largeR = componentRight[largeRoot];

        long added = 0;
        if (smallIsLeft) {
            for (int p = smallL; p <= smallR; p++) {
                int rank = heightRanks[p];
                int xKey = (p + 1) + heights[p];
                int yKey = (p + 1) - heights[p];

                long xResult = sumIndex.query(xKey + targetEnergy, largeL, largeR + 1, rank);
                added += getTotal(xResult) - getBelow(xResult);

                long yResult = diffIndex.query(yKey + targetEnergy, largeL, largeR + 1, rank);
                added += getBelow(yResult);
            }
        } else {
            for (int p = smallL; p <= smallR; p++) {
                int rank = heightRanks[p];
                int xKey = (p + 1) + heights[p];
                int yKey = (p + 1) - heights[p];

                long xResult = sumIndex.query(xKey - targetEnergy, largeL, largeR + 1, rank + 1);
                added += getBelow(xResult);

                long yResult = diffIndex.query(yKey - targetEnergy, largeL, largeR + 1, rank + 1);
                added += getTotal(yResult) - getBelow(yResult);
            }
        }

        currentPairs += added;

        parent[smallRoot] = largeRoot;
        componentLeft[largeRoot] = Math.min(componentLeft[largeRoot], componentLeft[smallRoot]);
        componentRight[largeRoot] = Math.max(componentRight[largeRoot], componentRight[smallRoot]);
        componentSize[largeRoot] += componentSize[smallRoot];
    }

    static void activate(int x) {
        active[x] = true;
        parent[x] = x;
        componentLeft[x] = componentRight[x] = x;
        componentSize[x] = 1;

        if (x > 0 && active[x - 1]) merge(x - 1, x);
        if (x + 1 < n && active[x + 1]) merge(x, x + 1);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        int q = fs.nextInt();
        targetEnergy = fs.nextInt();

        heights = new int[n];
        for (int i = 0; i < n; i++) heights[i] = fs.nextInt();

        int[] destroyed = new int[q];
        boolean[] initiallyDestroyed = new boolean[n];
        for (int i = 0; i < q; i++) {
            destroyed[i] = fs.nextInt() - 1;
            initiallyDestroyed[destroyed[i]] = true;
        }

        int[] sortedHeights = heights.clone();
        Arrays.sort(sortedHeights);
        int uniqueCount = 0;
        for (int value : sortedHeights) {
            if (uniqueCount == 0 || sortedHeights[uniqueCount - 1] != value) {
                sortedHeights[uniqueCount++] = value;
            }
        }
        int[] uniqueHeights = Arrays.copyOf(sortedHeights, uniqueCount);

        heightRanks = new int[n];
        for (int i = 0; i < n; i++) {
            heightRanks[i] = Arrays.binarySearch(uniqueHeights, heights[i]);
        }

        sumIndex = new StaticIndex(heights, heightRanks, uniqueCount, true);
        diffIndex = new StaticIndex(heights, heightRanks, uniqueCount, false);
        sumIndex.setCurrentRanks(heightRanks);
        diffIndex.setCurrentRanks(heightRanks);

        parent = new int[n];
        componentLeft = new int[n];
        componentRight = new int[n];
        componentSize = new int[n];
        active = new boolean[n];

        long[] answers = new long[q + 1];

        for (int i = 0; i < n; i++) {
            if (!initiallyDestroyed[i]) activate(i);
        }
        answers[q] = currentPairs;

        for (int t = q - 1; t >= 0; t--) {
            activate(destroyed[t]);
            answers[t] = currentPairs;
        }

        StringBuilder output = new StringBuilder();
        for (long answer : answers) output.append(answer).append('\n');
        System.out.print(output);
    }
}
